-- 往還録 歌川広重「東海道五十三次」（保永堂版）55図のシードデータ
-- 作成日：2026-09-29
-- 対応：docs/requirements.md 機能①（地点マスター）・機能⑤-A（人物ごとのアクセス権）
-- クラスタの一覧：docs/clusters-hiroshige.md
--
-- 【実行方法】
--   Supabase ダッシュボード → SQL Editor に貼り付けて実行する。
--   ステップは1つだけ（begin/commit で囲んであるため、途中で失敗しても何も入らない）。
--
-- 【実行前に確認すること】
--   1. 北斎のデータには影響しない。
--      このSQLは locations に広重の55行を INSERT するだけで、既存の行の UPDATE・DELETE はしない。
--      figure_id は「歌川広重」の行を名前で引く（北斎の slug='hokusai' とは別の行）。
--      北斎の地点は (figure_id, number) の一意制約で守られ、番号が重なっても衝突しない。
--   2. figures に「歌川広重」がちょうど1行あること（名前で引くため。0行だと
--      figure_id が null になり NOT NULL 制約でエラー、2行以上だとサブクエリがエラーになる。
--      どちらの場合も何も入らない）。
--        select id, slug, name from figures where name = '歌川広重';
--   3. まだ広重の地点が入っていないこと（2回実行すると一意制約でエラーになり、何も入らない）。
--        select count(*) from locations where figure_id = (select id from figures where name = '歌川広重');  -- 0件であること
--   4. 実行すると、人物を選ぶ画面（/figures）で広重が「準備中」から選べる状態に変わる
--      （地点が1件以上ある人物だけ選べる作り。app/figures/page.tsx）。
--      北斎を選んでいる人の画面（ホーム・地図・作品一覧）は、人物で絞り込んでいるため変わらない。
--      ただし記録タブ（/records）は全人物の記録を出す。
--   5. figure_entitlements（人物ごとのアクセス権、2026-08-21-phase1-schema.sql のステップ12）との関係：
--      requirements.md 機能⑤-Aは「北斎以外の人物の地点データを投入するタイミングで適用する」としている。
--      このSQLはステップ12を含まない。ステップ12を適用しないまま実行すると、
--      locations のSELECTは今まで通り「ログインしている全員が読める」ため、
--      広重の55図もログインできる全員に見える（北斎と同じ扱い）。
--      人物ごとに見せる人を絞りたい場合は、このSQLの前か後にステップ12を適用し、
--      自分に北斎と広重の両方のアクセス権を付与すること（ステップ12の末尾の insert は北斎だけなので、
--      f.slug = 'hokusai' の行をもう1つ、f.name = '歌川広重' で足す必要がある）。
--
-- 【取り消す場合】（広重の55行だけを消す。北斎の行には触れない）
--   ※ 広重の地点に紐づけた記録（records.location_id）がある場合は、外部キーのためエラーになる。
--     先に select count(*) from records where location_id in (select id from locations
--       where figure_id = (select id from figures where name = '歌川広重')); で0件を確認すること。
--   begin;
--   delete from locations where figure_id = (select id from figures where name = '歌川広重');
--   commit;
--
-- 【各列の決め方】
--   ・number / title_jp：保永堂版の55図の通し番号（日本橋=1〜京師=55）と、シリーズ名
--     「東海道五拾三次之内」（最後の1図は「東海道五拾三次大尾」）を除いた部分。
--     表記は東京都立図書館の題箋の通り（旧字体・異体字もそのまま。北斎と同じ方針）。
--   ・series：'保永堂版'（北斎の「正景」「裏富士」と同じく、版の区別に使う列）。
--   ・latitude / longitude：広重の描画地点は多くが特定されていないため、宿場の中心
--     （lib/tokaido-stations.ts の同じ宿場の座標。本陣跡・宿場の中心）を代表地点にした。
--     location_confidence は 'estimated'。
--     描画地点が広く知られている4図だけ、その地点を使った：
--       1 日本橋（橋そのもの）・55 三條大橋（橋そのもの）… 'confirmed'
--       17 由井 薩埵嶺（薩埵峠）… 'confirmed'
--       15 吉原 左冨士（名勝左富士・富士市依田橋町）… 地点は定説だが座標が町域の代表点のため 'estimated'
--     11 箱根 湖水圖は芦ノ湖と箱根の山を描くが、視点の位置に定説が見つからなかったため宿場の中心のまま。
--   ・accessibility_class / confidence / reason：北斎専用の「富士の見え方」の分類なので NULL
--     （列の制約は NULL を許す）。広重の図の多くは富士を描いていないため、分類自体が当てはまらない。
--   ・image_url：TOKYOアーカイブの表示用画像（size=view、約200KB）。2026-09-29に55件すべて
--     HTTP 200・image/jpeg で取得できること、詳細ページの題名が title_jp と一致することを確認した。
--   ・cluster / route_order：北斎と同じ「その日1日で往還できる単位」で、連続する宿場を25のまとまりに
--     分けた。route_order はクラスタ内で日本橋→京の順。一覧は docs/clusters-hiroshige.md。


-- ============================================================
-- 広重55図の投入
-- ============================================================

begin;

insert into locations
  (figure_id, number, title_jp, series, prefecture, modern_location, latitude, longitude, location_confidence, location_source, cluster, route_order, image_url, image_source, image_license)
values
  ((select id from figures where name = '歌川広重'), 1, '日本橋 行列振出', '保永堂版', '東京都', '中央区日本橋', 35.6837, 139.7744, 'confirmed', '日本橋そのものを描く（題名の通り）。座標は日本橋（Wikipedia「日本橋 (東京都中央区)」）', '武蔵・日本橋〜品川', 1, 'https://archive.library.metro.tokyo.lg.jp/da/download/?id=0000000003-00008133&size=view&type=image&file=%2F%E6%B5%AE%E4%B8%96%E7%B5%B5%2F061-C003-001.jpg', '東京都立図書館 TOKYOアーカイブ https://archive.library.metro.tokyo.lg.jp/da/detail?tilcod=0000000003-00008133', 'パブリックドメイン（東京都立図書館 TOKYOアーカイブ）'),
