  ((select id from figures where name = '歌川広重'), 3, '川崎 六郷渡舟', '保永堂版', '神奈川県', '川崎市川崎区', 35.5325, 139.7029, 'estimated', '宿場の中心を代表地点とした。描画地点は未特定（川崎宿の本陣跡・宿場の中心。座標の出典はlib/tokaido-stations.ts）', '武蔵・川崎〜保土ヶ谷', 1, 'https://archive.library.metro.tokyo.lg.jp/da/download/?id=0000000003-00008135&size=view&type=image&file=%2F%E6%B5%AE%E4%B8%96%E7%B5%B5%2F061-C003-003.jpg', '東京都立図書館 TOKYOアーカイブ https://archive.library.metro.tokyo.lg.jp/da/detail?tilcod=0000000003-00008135', 'パブリックドメイン（東京都立図書館 TOKYOアーカイブ）'),
